CREATE OR REPLACE FUNCTION public.finalize_fnb_cashier_closing_return(p_closing_id TEXT,p_performed_by TEXT) RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$ DECLARE v_closing public.cashier_closings%ROWTYPE; v_stock RECORD; v_now BIGINT := (extract(epoch from clock_timestamp())*1000)::bigint; v_total NUMERIC := 0; v_returned JSONB := '[]'::jsonb; v_items JSONB; BEGIN SELECT * INTO v_closing FROM public.cashier_closings WHERE closing_id=p_closing_id FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Closing kasir tidak ditemukan.'; END IF; IF v_closing.status='COMPLETED' THEN RETURN jsonb_build_object('success',true,'already_completed',true,'total_returned',v_closing.total_stock_returned,'items',v_closing.items); END IF; IF v_closing.status<>'READY_FOR_CLOCK_OUT' THEN RAISE EXCEPTION 'Status closing tidak mengizinkan pengembalian stok.'; END IF; FOR v_stock IN SELECT * FROM public.outlet_stocks WHERE business_id=v_closing.business_id AND outlet_id=v_closing.outlet_id AND stock_quantity>0 ORDER BY item_id FOR UPDATE LOOP UPDATE public.items SET stock_quantity=stock_quantity+v_stock.stock_quantity,updated_at=v_now WHERE business_id=v_closing.business_id AND item_id=v_stock.item_id; IF NOT FOUND THEN RAISE EXCEPTION 'Produk % tidak ditemukan pada stok divisi bisnis.',v_stock.item_name; END IF; UPDATE public.outlet_stocks SET stock_quantity=0,updated_at=v_now WHERE stock_id=v_stock.stock_id; INSERT INTO public.stan_transfers(transfer_id,transfer_reference,business_id,outlet_id,outlet_name,direction,item_id,item_name,quantity,timestamp,performed_by,notes,status,requested_by,requested_by_id,approved_by,processed_at) VALUES('strf-close-'||v_closing.closing_id||'-'||v_stock.item_id,'CLS-'||replace(v_closing.date_key,'-','')||'-'||right(v_stock.item_id,4),v_closing.business_id,v_closing.outlet_id,v_closing.outlet_name,'STAN_TO_PRODUCTION',v_stock.item_id,v_stock.item_name,v_stock.stock_quantity,v_now,p_performed_by,'Pengembalian otomatis seluruh sisa stok setelah closing kasir.','APPROVED',p_performed_by,v_closing.cashier_user_id,'AUTO CLOSING',v_now) ON CONFLICT(transfer_id) DO NOTHING; INSERT INTO public.stock_mutations(mutation_id,business_id,outlet_id,item_id,item_name,type,change_qty,final_qty,reference_id,note,performed_by,timestamp) VALUES('mut-close-'||v_closing.closing_id||'-'||v_stock.item_id,v_closing.business_id,v_closing.outlet_id,v_stock.item_id,v_stock.item_name,'TRANSFER_OUT',-v_stock.stock_quantity,0,v_closing.closing_id,'Pengembalian stok stan ke divisi bisnis setelah closing.',p_performed_by,v_now) ON CONFLICT(mutation_id) DO NOTHING; v_total:=v_total+v_stock.stock_quantity; v_returned:=v_returned||jsonb_build_array(jsonb_build_object('itemId',v_stock.item_id,'quantity',v_stock.stock_quantity)); END LOOP; SELECT COALESCE(jsonb_agg(jsonb_set(item,'{returned}',to_jsonb(COALESCE((SELECT (entry->>'quantity')::numeric FROM jsonb_array_elements(v_returned) AS entry WHERE entry->>'itemId'=item->>'itemId' LIMIT 1),0)),true)),'[]'::jsonb) INTO v_items FROM jsonb_array_elements(v_closing.items) AS item; UPDATE public.cashier_closings SET status='COMPLETED',total_stock_returned=v_total,items=v_items WHERE closing_id=p_closing_id; RETURN jsonb_build_object('success',true,'already_completed',false,'total_returned',v_total,'items',v_returned); END; $$; GRANT EXECUTE ON FUNCTION public.finalize_fnb_cashier_closing_return(TEXT,TEXT) TO anon,authenticated;
